import { useEffect, useRef, useState } from 'react'

/**
 * Replays real pipeline output for talking.MOV (generated by running lipread/ on it),
 * synced to the clip itself: the face, the 96×96 mouth crops the model saw, the
 * jawOpen signal that segments phrases, and the partial / final decodes.
 */
type ReplayData = {
  fps: number
  frames: number
  cols: number
  size: number
  jaw: number[]
  clipStart: number
  phraseStart: number
  phraseEnd: number
  partials: { frame: number; text: string }[]
  final: string
}

const HOLD_MS = 2600 // how long the final line stays up before the clip restarts
const START = 0.1
const STILL = 0.04
const JAW_MAX = 0.6

export function Replay() {
  const [data, setData] = useState<ReplayData | null>(null)
  const [frame, setFrame] = useState(0)
  const [done, setDone] = useState(false)
  const videoRef = useRef<HTMLVideoElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const spriteRef = useRef<HTMLImageElement | null>(null)

  useEffect(() => {
    fetch('/landing/replay.json')
      .then((r) => r.json())
      .then(setData)
      .catch(() => {})
    const img = new Image()
    img.src = '/landing/mouth-sprite.png'
    spriteRef.current = img
  }, [])

  // the video is the clock: frame = its time at the pipeline's 25 fps
  useEffect(() => {
    const v = videoRef.current
    if (!data || !v) return
    const last = data.frames - 1
    const showFinal = () => {
      setFrame(last)
      setDone(true)
    }
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) {
      v.pause()
      const seek = () => (v.currentTime = Math.max(0, v.duration - 0.05))
      if (v.readyState >= 1) seek()
      else v.addEventListener('loadedmetadata', seek, { once: true })
      showFinal()
      return
    }

    let raf = 0
    let hold = 0
    let visible = true
    const tick = () => {
      raf = requestAnimationFrame(tick)
      if (v.ended) return
      setFrame(Math.min(Math.floor(v.currentTime * data.fps), last))
      setDone(false)
    }
    const onEnded = () => {
      showFinal()
      hold = window.setTimeout(() => {
        v.currentTime = 0
        if (visible) v.play().catch(showFinal)
      }, HOLD_MS)
    }
    v.addEventListener('ended', onEnded)
    v.play().catch(showFinal)
    raf = requestAnimationFrame(tick)

    // only run while the card is on screen
    const io = new IntersectionObserver(([e]) => {
      visible = e.isIntersecting
      if (!visible) v.pause()
      else if (!v.ended) v.play().catch(() => {})
    })
    io.observe(v)

    return () => {
      cancelAnimationFrame(raf)
      clearTimeout(hold)
      io.disconnect()
      v.removeEventListener('ended', onEnded)
    }
  }, [data])

  // draw the current mouth crop, nearest-neighbour so the 96 px input stays visible
  useEffect(() => {
    const c = canvasRef.current
    const img = spriteRef.current
    if (!c || !img || !data) return
    const draw = () => {
      const ctx = c.getContext('2d')!
      ctx.imageSmoothingEnabled = false
      const s = data.size
      ctx.drawImage(img, (frame % data.cols) * s, Math.floor(frame / data.cols) * s, s, s, 0, 0, c.width, c.height)
    }
    if (img.complete) draw()
    else img.onload = draw
  }, [frame, data])

  const frames = data?.frames ?? 78
  const fps = data?.fps ?? 25
  const jaw = data?.jaw ?? []
  const reading = !!data && frame >= data.phraseStart
  const partial = data && [...data.partials].reverse().find((p) => p.frame <= frame && p.text)
  const text = done ? data!.final : reading ? (partial?.text ?? '') : ''
  const state = done ? 'Decoded' : reading ? 'Reading lips' : 'Watching'

  // jaw graph
  const W = 600
  const H = 132
  const x = (i: number) => (i / (frames - 1)) * W
  const y = (v: number) => H - (Math.min(v, JAW_MAX) / JAW_MAX) * H
  const points = jaw.map((v, i) => `${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ')
  const area = jaw.length ? `0,${H} ${points} ${W},${H}` : ''

  return (
    <figure className="rp" aria-label={`A real clip, read by the Unspoken pipeline as "${data?.final ?? ''}"`}>
      <div className="rp-face">
        <video
          ref={videoRef}
          src="/landing/talking.mp4"
          poster="/landing/talking-poster.jpg"
          muted
          playsInline
          preload="auto"
          aria-hidden
        />
        <span className={`rp-roi ${reading && !done ? 'is-hot' : ''}`} aria-hidden>
          <i />
        </span>
        <span className="rp-src">Real clip, no sound</span>
      </div>

      <div className="rp-body">
        <header className="rp-head">
          <span className={`rp-state ${done ? 'is-final' : reading ? 'is-live' : ''}`}>
            <i />
            {state}
          </span>
          <span className="rp-clock">
            {String(frame + 1).padStart(2, '0')}/{frames} · {(frame / fps).toFixed(2)} s
          </span>
        </header>

        <p className="rp-text" aria-live="off">
          {/* word by word, keyed by position, so only newly decoded words animate in */}
          {text
            .split(' ')
            .filter(Boolean)
            .map((w, i) => (
              <span key={`${i}-${w}`}>
                {i > 0 && ' '}
                <span className="rp-word">{i === 0 ? w[0].toUpperCase() + w.slice(1) : w}</span>
              </span>
            ))}
          {!done && <span className="rp-caret" />}
        </p>

        <div className="rp-signal">
          <div className="rp-model">
            <span className="rp-chip">
              <canvas ref={canvasRef} width={192} height={192} />
            </span>
            <span className="rp-chip-cap">
              What the model sees
              <small>96 × 96 px</small>
            </span>
          </div>

          <div className="rp-graph-wrap">
            <div className="rp-graph-head">
              <span>Jaw opening</span>
              <span className="rp-value">{(jaw[frame] ?? 0).toFixed(2)}</span>
            </div>
            <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" className="rp-graph" aria-hidden>
              {data && (
                <rect
                  x={x(data.clipStart)}
                  y={0}
                  width={x(frames - 1) - x(data.clipStart)}
                  height={H}
                  className="rp-clip"
                />
              )}
              <line x1={0} x2={W} y1={y(START)} y2={y(START)} className="rp-th rp-th-start" />
              <line x1={0} x2={W} y1={y(STILL)} y2={y(STILL)} className="rp-th" />
              <polygon points={area} className="rp-area" />
              <polyline points={points} className="rp-line" />
              <line x1={x(frame)} x2={x(frame)} y1={0} y2={H} className="rp-head-line" />
            </svg>
            <div className="rp-legend">
              <span>
                <i className="rp-key rp-key-start" /> Starts a phrase
              </span>
              <span>
                <i className="rp-key" /> Pause
              </span>
              <span>
                <i className="rp-key rp-key-clip" /> Sent to the model
              </span>
            </div>
          </div>
        </div>
      </div>
    </figure>
  )
}
